ALTER TABLE patients ADD COLUMN allergies text;
CREATE TYPE visit_status AS ENUM('IN_PROGRESS','COMPLETED','CANCELLED');
CREATE TABLE visits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),appointment_id uuid UNIQUE REFERENCES appointments(id) ON DELETE RESTRICT,queue_entry_id uuid UNIQUE REFERENCES queue_entries(id) ON DELETE RESTRICT,patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE RESTRICT,doctor_id uuid NOT NULL REFERENCES doctors(id) ON DELETE RESTRICT,status visit_status NOT NULL DEFAULT 'IN_PROGRESS',chief_complaint text,history_of_present_illness text,physical_examination text,clinical_findings text,treatment_plan text,follow_up text,additional_notes text,started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());CREATE INDEX visits_patient_idx ON visits(patient_id);CREATE INDEX visits_doctor_idx ON visits(doctor_id);CREATE INDEX visits_started_idx ON visits(started_at);
CREATE TABLE vital_signs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),visit_id uuid NOT NULL UNIQUE REFERENCES visits(id) ON DELETE CASCADE,systolic integer,diastolic integer,heart_rate integer,respiratory_rate integer,temperature numeric(4,1),spo2 integer,weight numeric(5,2),height numeric(5,2),recorded_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT vital_systolic_check CHECK(systolic BETWEEN 40 AND 300),CONSTRAINT vital_diastolic_check CHECK(diastolic BETWEEN 20 AND 200),CONSTRAINT vital_spo2_check CHECK(spo2 BETWEEN 0 AND 100));
CREATE TABLE diagnoses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),icd10_code text NOT NULL UNIQUE,name text NOT NULL,description text,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());CREATE INDEX diagnoses_name_idx ON diagnoses(name);
CREATE TABLE visit_diagnoses(visit_id uuid NOT NULL REFERENCES visits(id) ON DELETE CASCADE,diagnosis_id uuid NOT NULL REFERENCES diagnoses(id) ON DELETE RESTRICT,is_primary boolean NOT NULL DEFAULT false,notes text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(visit_id,diagnosis_id));CREATE UNIQUE INDEX visit_diagnoses_primary_uidx ON visit_diagnoses(visit_id) WHERE is_primary=true;CREATE INDEX visit_diagnoses_visit_idx ON visit_diagnoses(visit_id);
